    rdf:reifies <https://example.org/openevidence/generated/ev_q_hepatitis_c_efficacy_0-tt> ;
    holon:confidence "0.56"^^xsd:decimal ;
    holon:evidenceLevel "Level-3" ;
    holon:assessedBy <https://example.org/openevidence/questions/openevidence_ai> ;
    holon:recordedOn "2026-12-31"^^xsd:date ;
    oe:cites <https://example.org/openevidence/sources/39914746> ;
    holon:inHolon <https://example.org/openevidence/questions/q_hepatitis_c_efficacy> ;
    oe:effectiveness "effective" .
